import{_ as s,o as e,c as t,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"用户和用户组","description":"","frontmatter":{},"headers":[],"relativePath":"system-config/users.md","filePath":"system-config/users.md","lastUpdated":1792000532000}'),p={name:"system-config/users.md"};function i(o,a,d,l,c,h){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="用户和用户组" tabindex="-1">用户和用户组 <a class="header-anchor" href="#用户和用户组" aria-label="Permalink to &quot;用户和用户组&quot;">​</a></h1><p>Linux 用户相关的信息分散在几个文件里：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/etc/passwd    用户及其属性信息</span></span>
<span class="line"><span>/etc/shadow    用户密码及其相关属性</span></span>
<span class="line"><span>/etc/group     组及其属性信息</span></span>
<span class="line"><span>/etc/gshadow   组密码及其相关属性</span></span></code></pre></div><h2 id="用户" tabindex="-1">用户 <a class="header-anchor" href="#用户" aria-label="Permalink to &quot;用户&quot;">​</a></h2><h3 id="创建用户" tabindex="-1">创建用户 <a class="header-anchor" href="#创建用户" aria-label="Permalink to &quot;创建用户&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>useradd -m -s /usr/bin/bash xnamex</span></span></code></pre></div><p><code>-m</code> 自动创建家目录，<code>-s</code> 指定登录 shell。</p><p>删除用户（<code>-r</code> 连同家目录一起删）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>userdel username -r</span></span></code></pre></div><h3 id="修改用户信息" tabindex="-1">修改用户信息 <a class="header-anchor" href="#修改用户信息" aria-label="Permalink to &quot;修改用户信息&quot;">​</a></h3><p>改用户名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usermod -l newname oldname</span></span></code></pre></div><p>迁移家目录到新位置（<code>-m</code> 会移动现有文件）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usermod -d /new/home -m username</span></span></code></pre></div><p>锁定 / 解锁用户（锁定后无法登录）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usermod -L username</span></span>
<span class="line"><span>usermod -U username</span></span></code></pre></div><h2 id="用户组" tabindex="-1">用户组 <a class="header-anchor" href="#用户组" aria-label="Permalink to &quot;用户组&quot;">​</a></h2><h3 id="创建组" tabindex="-1">创建组 <a class="header-anchor" href="#创建组" aria-label="Permalink to &quot;创建组&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>groupadd groupname</span></span></code></pre></div><p>修改用户组属性：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>groupmod groupname</span></span></code></pre></div><p>删除用户组：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>groupdel groupname</span></span></code></pre></div><h3 id="把用户加入组" tabindex="-1">把用户加入组 <a class="header-anchor" href="#把用户加入组" aria-label="Permalink to &quot;把用户加入组&quot;">​</a></h3><p>追加到附加组（多个组用逗号分隔）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usermod -aG group1,group2 username</span></span></code></pre></div><blockquote><p><code>-a</code> 表示追加（append），<code>-G</code> 指定附加组。不加 <code>-a</code> 会覆盖用户原来的附加组，务必带上 <code>-a</code>。</p></blockquote><h2 id="sudo-权限" tabindex="-1">sudo 权限 <a class="header-anchor" href="#sudo-权限" aria-label="Permalink to &quot;sudo 权限&quot;">​</a></h2><p>配置文件在 <code>/etc/sudoers</code>（用 <code>visudo</code> 编辑，会检查语法）。</p><p>方式一：把用户加到 sudo 组（推荐，方便维护）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>usermod -aG wheel 用户名</span></span></code></pre></div><p>方式二：直接给单个用户加 sudo 权限：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xxx ALL=(ALL:ALL) ALL</span></span></code></pre></div>`,33)])])}const g=s(p,[["render",i]]);export{u as __pageData,g as default};
